{
  "title": "The Rescue of the Lost Heir",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "A worn map points the way into the ruined city.",
      "visual_description": "Dawn on a windy ridge above a shattered skyline of broken spires; a cloaked map reader holds an old parchment while a scout crouches beside her, peering through a spyglass.",
      "characters": ["Maren the Cartographer", "Jex the Scout"]
    },
    {
      "scene_number": 2,
      "caption": "The rescue team gathers at the old shrine.",
      "visual_description": "A crumbling stone shrine overgrown with ivy; four travelers stand in a half-circle around a flickering blue flame, packs at their feet.",
      "characters": ["Maren the Cartographer", "Jex the Scout", "Wisp the Mage", "Sir Bromwell"]
    },
    {
      "scene_number": 3,
      "caption": "They approach the cracked castle gates.",
      "visual_description": "Massive iron-banded gates split down the middle, the royal crest defaced; the team peers through the gap into a fog-choked courtyard.",
      "characters": ["Maren the Cartographer", "Jex the Scout", "Wisp the Mage", "Sir Bromwell"]
    },
    {
      "scene_number": 4,
      "caption": "A frightened townswoman warns them away.",
      "visual_description": "A thin woman in a patched shawl clutches a basket of turnips at a side alley, eyes wide as she whispers to the cloaked map reader under a leaning lamppost.",
      "characters": ["Maren the Cartographer", "Hesla the Townswoman"]
    },
    {
      "scene_number": 5,
      "caption": "Armored patrols march through the plaza.",
      "visual_description": "A column of black-armored soldiers crosses a rubble-strewn plaza beneath tattered royal banners; the team hides behind a toppled statue of a king.",
      "characters": ["Jex the Scout", "Sir Bromwell", "Captain Vorr"]
    },
    {
      "scene_number": 6,
      "caption": "Rumors of a dragon echo through the marketplace.",
      "visual_description": "A boarded-up market with overturned stalls; an old beggar gestures wildly toward distant smoke as Jex listens, one hand on his dagger.",
      "characters": ["Jex the Scout", "Old Ralic the Beggar"]
    },
    {
      "scene_number": 7,
      "caption": "The cursed tower looms over the team.",
      "visual_description": "A black spiral tower wreathed in greenish mist; Wisp the Mage holds up a glowing staff while the others shield their eyes from a sickly glare.",
      "characters": ["Maren the Cartographer", "Jex the Scout", "Wisp the Mage", "Sir Bromwell"]
    },
    {
      "scene_number": 8,
      "caption": "Wisp deciphers the warding runes.",
      "visual_description": "Close-up of a stone archway carved with luminous runes; Wisp traces a sigil in the air with two glowing fingers, her hood thrown back.",
      "characters": ["Wisp the Mage"]
    },
    {
      "scene_number": 9,
      "caption": "A sleepy royal clerk is found in the gatehouse.",
      "visual_description": "A pudgy man in a stained official tabard snores at a tilted desk piled with scrolls; Sir Bromwell pokes him with the flat of his sword as Maren rifles a ledger.",
      "characters": ["Maren the Cartographer", "Sir Bromwell", "Clerk Pim"]
    },
    {
      "scene_number": 10,
      "caption": "The clerk reveals where the heir is held.",
      "visual_description": "Pim, now wide-eyed and clutching a candle, points trembling at a marked floor plan unrolled across the desk; the team leans in over his shoulders.",
      "characters": ["Maren the Cartographer", "Jex the Scout", "Wisp the Mage", "Sir Bromwell", "Clerk Pim"]
    },
    {
      "scene_number": 11,
      "caption": "A magic door blocks the inner keep.",
      "visual_description": "A tall door of polished obsidian set with seven shifting silver glyphs; the corridor floor is patterned with faintly pulsing veins of light.",
      "characters": ["Wisp the Mage", "Sir Bromwell"]
    },
    {
      "scene_number": 12,
      "caption": "Wisp unlocks the door with a whispered word.",
      "visual_description": "The obsidian door splits open in a fan of pale light; Wisp lowers her staff, breath steaming, as Sir Bromwell shoulders past with sword drawn.",
      "characters": ["Wisp the Mage", "Sir Bromwell"]
    },
    {
      "scene_number": 13,
      "caption": "They find the captive heir chained in the throne room.",
      "visual_description": "A vaulted throne room with shattered stained glass; a young heir in tattered finery sits chained to the base of a cracked throne, looking up with relief.",
      "characters": ["Maren the Cartographer", "Jex the Scout", "Wisp the Mage", "Sir Bromwell", "Prince Aldric"]
    },
    {
      "scene_number": 14,
      "caption": "Captain Vorr confronts the rescuers.",
      "visual_description": "A black-armored captain blocks the throne room arch, helm under one arm, a long curved blade leveled; soldiers form up behind him in the smoky hall.",
      "characters": ["Sir Bromwell", "Wisp the Mage", "Prince Aldric", "Captain Vorr"]
    },
    {
      "scene_number": 15,
      "caption": "Sir Bromwell holds the line so the others can flee.",
      "visual_description": "Sparks fly as Bromwell parries Vorr's blade in a narrow corridor while Maren pulls the prince by the wrist toward a side stairwell.",
      "characters": ["Sir Bromwell", "Captain Vorr", "Maren the Cartographer", "Prince Aldric"]
    },
    {
      "scene_number": 16,
      "caption": "They race through burning streets toward the river.",
      "visual_description": "Tattered royal banners flap above a street of burning timbers; the team sprints past frightened townsfolk, Wisp casting a shimmering shield behind them.",
      "characters": ["Maren the Cartographer", "Jex the Scout", "Wisp the Mage", "Prince Aldric", "Hesla the Townswoman"]
    },
    {
      "scene_number": 17,
      "caption": "The old stone bridge cracks beneath their feet.",
      "visual_description": "A narrow arched bridge over a black river; stones split and fall as Jex hauls the prince forward, Wisp gesturing to hold the span together with golden threads of magic.",
      "characters": ["Jex the Scout", "Wisp the Mage", "Prince Aldric", "Maren the Cartographer"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far shore, they look back at the ruined city.",
      "visual_description": "On a misty bank at dawn, the four rescuers and the prince stand in silhouette against the burning skyline, Bromwell limping up last with his blade lowered.",
      "characters": ["Maren the Cartographer", "Jex the Scout", "Wisp the Mage", "Sir Bromwell", "Prince Aldric"]
    }
  ]
}

